);
alter table public.exercise_attempts enable row level security;
create policy "own attempts read" on public.exercise_attempts for select using (user_id = auth.uid());
create index if not exists exercise_attempts_user_idx on public.exercise_attempts (user_id, created_at desc);

-- ===== migrations/0008_admin.sql =====
-- Admin accounts: full access without limits.
-- The admins table has row level security and NO policies, so no client can read or change it.
-- Only the SQL editor / service role (postgres) can add admins, see grant_admin below.
create table if not exists public.admins (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  note text,
  created_at timestamptz not null default now()
);
alter table public.admins enable row level security;

create or replace function public.is_admin(p_user uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.admins where user_id = p_user);
$$;
revoke all on function public.is_admin(uuid) from public, anon, authenticated;

-- Self-only check for the app and the edge functions.
create or replace function public.is_admin_self() returns boolean
language sql stable security definer set search_path = public as $$
  select public.is_admin(auth.uid());
$$;
grant execute on function public.is_admin_self() to authenticated;

-- Admins count as premium everywhere (is_premium_self, consume_ai_request, can_analyze_voice all use it),
-- so they have unlimited AI requests, unlimited voice analyses and every premium feature.
create or replace function public.is_premium(p_user uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select public.is_admin(p_user) or exists (
    select 1 from public.subscriptions
    where user_id = p_user
      and (
        (status in ('active', 'trialing', 'past_due') and current_period_end + interval '3 days' > now())
        or (status = 'canceled' and current_period_end > now())
      )
  );
$$;

-- Grants admin rights to an existing account (the person must have signed up first).
-- Run in the Supabase SQL editor:  select public.grant_admin('you@example.com');
create or replace function public.grant_admin(p_email text) returns void
language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  select id into v_id from auth.users where lower(email) = lower(p_email);
  if v_id is null then raise exception 'No account with email %', p_email; end if;
  insert into public.admins (user_id, note) values (v_id, 'granted via grant_admin') on conflict do nothing;
end $$;

create or replace function public.revoke_admin(p_email text) returns void
language plpgsql security definer set search_path = public as $$
begin
  delete from public.admins where user_id = (select id from auth.users where lower(email) = lower(p_email));
end $$;

revoke all on function public.grant_admin(text) from public, anon, authenticated;
revoke all on function public.revoke_admin(text) from public, anon, authenticated;

-- ===== migrations/0009_paid_access.sql =====
-- Pay first: all product content is readable only with an active membership (or an admin account).
-- Before this migration any signed-in account could read the content tables through the API.
-- is_premium_self() is true for paying members, trial users, the payment grace period and admins.

drop policy if exists "content read lines" on public.lines;
drop policy if exists "content read challenges" on public.challenges;
drop policy if exists "exercises read" on public.exercises;

create policy "paid read lines" on public.lines for select to authenticated using (public.is_premium_self());
create policy "paid read challenges" on public.challenges for select to authenticated using (public.is_premium_self());
create policy "paid read exercises" on public.exercises for select to authenticated using (public.is_premium_self());

-- Voice uploads need a membership too.
drop policy if exists "voice upload own" on storage.objects;
create policy "voice upload own" on storage.objects for insert to authenticated
  with check (bucket_id = 'voice' and (storage.foldername(name))[1] = auth.uid()::text and public.is_premium_self());

-- Earning XP and scores needs a membership (the function is security definer, so check inside).
create or replace function public.complete_challenge(p_challenge_id uuid, p_result int) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_skill text;
  v_last date;
  v_streak int;
  v_old int;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if not public.is_premium(v_uid) then raise exception 'membership required'; end if;
  if p_result not between 1 and 3 then raise exception 'invalid result'; end if;
  select skill into v_skill from public.challenges where id = p_challenge_id;
  if v_skill is null then raise exception 'unknown challenge'; end if;

  insert into public.user_challenges (user_id, challenge_id, result)
  values (v_uid, p_challenge_id, p_result)
  on conflict (user_id, day) do nothing;
  if not found then return; end if;           -- already completed today

  select last_active, streak into v_last, v_streak from public.gamification where user_id = v_uid;
  v_streak := case when v_last = current_date - 1 then v_streak + 1 else 1 end;
  update public.gamification
     set xp = xp + 20 + p_result * 5 + least(v_streak, 7) * 2,
         streak = v_streak,
         longest_streak = greatest(longest_streak, v_streak),
         last_active = current_date
   where user_id = v_uid;

  select score into v_old from public.skill_scores
    where user_id = v_uid and skill = v_skill order by measured_at desc, id desc limit 1;
  insert into public.skill_scores (user_id, skill, score)
    values (v_uid, v_skill, least(100, coalesce(v_old, 40) + 3));
  select score into v_old from public.skill_scores
    where user_id = v_uid and skill = 'confidence' order by measured_at desc, id desc limit 1;
  insert into public.skill_scores (user_id, skill, score)
    values (v_uid, 'confidence', least(100, coalesce(v_old, 40) + 2));
end $$;

revoke all on function public.complete_challenge(uuid, int) from public, anon;
grant execute on function public.complete_challenge(uuid, int) to authenticated;

-- ===== migrations/0010_sections.sql =====
-- Section cards (Deep Talk, Business, Speak Better) live in the database, not in the app code,
-- so nothing of the product content ships inside the free app download or the public web files.
create table if not exists public.sections (
  id uuid primary key default gen_random_uuid(),
  track text not null check (track in ('deep_talk', 'business', 'speak')),
  position int not null default 0,
  title text not null,
  tags text[] not null default '{}',
  detail_label text not null default '',
  details text[] not null default '{}',
  route text,                               -- optional in-app screen to open (for example /studio/voice)
  unique (track, title)
);
alter table public.sections enable row level security;
create policy "paid read sections" on public.sections for select to authenticated using (public.is_premium_self());

-- ===== migrations/0011_fair_use.sql =====
-- Fair use: paying members get a high daily cap on AI requests and voice analyses so that a bug, a stolen
-- login or abuse cannot run up the AI bill. Admins stay unlimited. Accounts without a membership cannot
-- reach the AI at all (pay first); their limit only matters if REQUIRE_PREMIUM is switched off.

drop function if exists public.consume_ai_request(int);

create or replace function public.consume_ai_request(p_free_limit int default 5, p_member_limit int default 300)
returns boolean language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_count int;
  v_limit int;
begin
  if v_uid is null then return false; end if;
  insert into public.ai_usage (user_id, day, requests) values (v_uid, current_date, 0)
    on conflict (user_id, day) do nothing;
  select requests into v_count from public.ai_usage
    where user_id = v_uid and day = current_date for update;
  v_limit := case
    when public.is_admin(v_uid) then null             -- admins: unlimited
    when public.is_premium(v_uid) then p_member_limit -- members: fair use cap
    else p_free_limit
  end;
  if v_limit is not null and v_count >= v_limit then return false; end if;
  update public.ai_usage set requests = requests + 1 where user_id = v_uid and day = current_date;
  return true;
end $$;

revoke all on function public.consume_ai_request(int, int) from public, anon;
grant execute on function public.consume_ai_request(int, int) to authenticated;

-- Voice analyses: admins unlimited, members up to 20 per day, accounts without a membership 1 per week.
create or replace function public.can_analyze_voice() returns boolean
language sql stable security definer set search_path = public as $$
  select public.is_admin(auth.uid())
      or case when public.is_premium(auth.uid())
           then (select count(*) from public.voice_analyses
                 where user_id = auth.uid() and created_at > now() - interval '1 day') < 20
           else not exists (select 1 from public.voice_analyses
                 where user_id = auth.uid() and created_at > now() - interval '7 days')
         end;
$$;
grant execute on function public.can_analyze_voice() to authenticated;
